// A dashboard editor can deploy this single generated file; no credentials included.
import {readFile,writeFile} from 'node:fs/promises';
const handler=await readFile('supabase/functions/scan-roster/handler.ts','utf8');
const entry=(await readFile('supabase/functions/scan-roster/index.ts','utf8')).replace(/^import .*\n/,'');
const output='supabase/scan-roster-dashboard.ts';
const contents='// Generated by node scripts/prepare-scan-function.mjs. No secrets belong in this file.\n'+handler+'\n'+entry;
if(process.argv.includes('--check')){if(await readFile(output,'utf8')!==contents)throw new Error('Regenerate scan dashboard file');console.log('Scan dashboard file matches tested function.');}
else{await writeFile(output,contents);console.log('Prepared single-file scan function; no deployment performed.');}
